from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """

    def is_valid_parentheses(string: str) -> bool:
        stack = []
        for char in string:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return len(stack) == 0

    def separate_group(string: str, index: int) -> List[str]:
        group = string[index:]
        while index > 0 and group[index - 1] != '(':
            index -= 1
        if is_valid_parentheses(group):
            return [group] + separate_group(string, index)
        else:
            return []

    result = []
    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            stack.append(i)
        elif paren_string[i] == ')':
            index = stack.pop()
            result.append(separate_group(paren_string, index))
        i += 1

    return result
