def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b c a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """

    # Convert the string to lowercase and split it into a list of characters
    test = test.lower()
    char_list = list(test)

    # Create an empty dictionary to store the counts of each character
    count_dict = {}

    # Iterate over the list of characters and update their corresponding counts in the dictionary
    for char in char_list:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1

    # Return the dictionary containing the character with the most repetition and its corresponding count
    return max(count_dict, key=count_dict.get)
