def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""

    # Check if n is prime
    if n < 2 or n % 2 == 0:
        return 1
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i

    # If n is not prime, find its largest prime factor
    factors = []
    for i in range(2, n):
        while n % i == 0:
            factors.append(i)
            n //= i

    if len(factors) > 1:
        return max(factors)
    else:
        return 1
