from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """

    def count_levels(string: str) -> int:
        levels = 0
        for i in range(len(string)):
            if string[i] == '(':
                levels += 1
            elif string[i] == ')':
                levels -= 1
        return levels

    def find_max_levels(string: str) -> int:
        max_levels = -1
        for i in range(len(string)):
            if string[i] == '(':
                level = count_levels(string[:i])
                if level > max_levels:
                    max_levels = level
        return max_levels

    levels = []
    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            levels.append(find_max_levels(paren_string[:i]))
        elif paren_string[i] == ')':
            levels.pop()

    return levels
